package com.sakti.banking.service;
import com.sakti.banking.dto.*; import com.sakti.banking.entity.*; import com.sakti.banking.exception.*; import com.sakti.banking.repository.UserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class UserService { private final UserRepository users; private final PasswordEncoder encoder; private final AuditService audit; public UserService(UserRepository u,PasswordEncoder e,AuditService a){users=u;encoder=e;audit=a;} @Transactional public UserResponse register(RegisterRequest r){if(users.existsByEmailIgnoreCase(r.email()))throw new BusinessException("Email already registered"); AppUser u=new AppUser();u.setFullName(r.fullName().trim());u.setEmail(r.email().trim().toLowerCase());u.setPassword(encoder.encode(r.password()));u.setRole(Role.CUSTOMER);u=users.save(u);audit.record(u.getEmail(),"REGISTER","USER","SUCCESS");return UserResponse.from(u);} public AppUser requireByEmail(String e){return users.findByEmailIgnoreCase(e).orElseThrow(()->new ResourceNotFoundException("User not found"));} @Transactional public UserResponse updateProfile(String email,ProfileUpdateRequest r){AppUser u=requireByEmail(email);u.setFullName(r.fullName().trim());u.setPhone(r.phone());u.setAddress(r.address());u.setDateOfBirth(r.dateOfBirth());u.setNomineeName(r.nomineeName());u.setNomineeRelation(r.nomineeRelation());audit.record(email,"PROFILE_UPDATE","USER","SUCCESS");return UserResponse.from(u);} public List<UserResponse> allUsers(){return users.findAll().stream().map(UserResponse::from).toList();} }
